async def retry_with_backoff(operation: Callable[[], Awaitable[T]], *, max_retries: int=3, initial_backoff: float=2.0, max_backoff: float=60.0, max_total_time: float | None=None, operation_name: str='operation') -> T:
    """Execute an async operation with exponential backoff on retryable errors.

    Retries on:
    - httpx.TimeoutException
    - httpx.ConnectError, httpx.ConnectTimeout, httpx.NetworkError
    - httpx.HTTPStatusError with status 429, 503, 406

    Note: HTTP 406 uses minimal retries (ARXIV_HTTP_406_MAX_RETRIES = 1)
    because arXiv's 406 is IP-level burst throttling and retrying inside
    the window extends the block (#277).

    Args:
        operation: Async callable to execute.
        max_retries: Maximum number of retry attempts (for 429/503).
        initial_backoff: Initial backoff delay in seconds.
        max_backoff: Maximum backoff delay in seconds.
        max_total_time: Optional maximum total time in seconds (raises on exceed).
        operation_name: Name for logging.

    Returns:
        Result of the operation.

    Raises:
        Original exception after exhausting retries, wrapped with context.
    """
    from .config import Settings
    settings = Settings()
    start_time = time.monotonic()
    last_exception: Exception | None = None
    retry_after: str | None = None
    for attempt in range(max_retries + 1):
        if max_total_time is not None:
            elapsed = time.monotonic() - start_time
            if elapsed >= max_total_time:
                attempts_word = 'attempt' if attempt == 0 else 'attempts'
                logger.error('%s exceeded max total time %.1fs after %d %s', operation_name, max_total_time, attempt, attempts_word)
                if last_exception:
                    raise ArxivTimeoutError(f'{operation_name} timed out after {max_total_time:.0f}s. The arXiv API may be slow or overloaded. Please retry shortly.') from last_exception
                raise ArxivTimeoutError(f'{operation_name} timed out after {max_total_time:.0f}s. The arXiv API may be slow or overloaded. Please retry shortly.')
        try:
            if max_total_time is not None:
                remaining = max_total_time - (time.monotonic() - start_time)
                if remaining <= 0:
                    raise asyncio.TimeoutError('Budget exhausted before attempt')
                logger.debug('%s attempt %d with %.1fs budget', operation_name, attempt + 1, remaining)
                return await asyncio.wait_for(operation(), timeout=remaining)
            return await operation()
        except asyncio.TimeoutError as e:
            if max_total_time is not None:
                elapsed = time.monotonic() - start_time
                logger.error('%s timed out after %.1fs (budget: %.1fs)', operation_name, elapsed, max_total_time)
                if last_exception and isinstance(last_exception, httpx.HTTPStatusError):
                    status_code = last_exception.response.status_code
                    if status_code in (429, 503, 406):
                        retry_after = 60.0 if status_code != 406 else 600.0
                        raise ArxivRateLimitError(f'arXiv is rate limiting this IP (HTTP {status_code}). Please wait {int(retry_after)} seconds before retrying.', status_code=status_code, retry_after_seconds=retry_after) from e
                raise ArxivTimeoutError(f'arXiv request timed out after {int(elapsed)}s. The arXiv API may be slow or overloaded. Please retry shortly.') from e
            raise
        except (httpx.ConnectError, httpx.ConnectTimeout, httpx.NetworkError) as e:
            last_exception = e
            if attempt < max_retries:
                wait = _compute_backoff_seconds(attempt, None, initial_backoff, max_backoff)
                if max_total_time is not None:
                    remaining = max_total_time - (time.monotonic() - start_time)
                    if wait >= remaining:
                        logger.warning('%s insufficient budget for retry (%.1fs < %.1fs wait)', operation_name, remaining, wait)
                        raise ArxivConnectionError(f'Could not connect to arXiv after {attempt + 1} attempts. Please check your network connection and retry shortly.') from e
                    wait = min(wait, remaining * 0.9)
                logger.warning('%s connection error; retrying in %.1fs (attempt %d/%d)', operation_name, wait, attempt + 1, max_retries + 1)
                await asyncio.sleep(wait)
            else:
                logger.error('%s connection failed after %d attempts', operation_name, max_retries + 1)
                raise ArxivConnectionError(f'Could not connect to arXiv after {max_retries + 1} attempts. Please check your network connection and retry shortly.') from e
        except httpx.TimeoutException as e:
            last_exception = e
            if attempt < max_retries:
                wait = _compute_backoff_seconds(attempt, None, initial_backoff, max_backoff)
                if max_total_time is not None:
                    remaining = max_total_time - (time.monotonic() - start_time)
                    if wait >= remaining or remaining <= 0.1:
                        logger.warning('%s insufficient budget for retry (%.1fs remaining, %.1fs wait needed)', operation_name, remaining, wait)
                        raise ArxivTimeoutError(f'arXiv request timed out after {attempt + 1} attempts. The arXiv API may be slow or overloaded. Please retry shortly.') from e
                    wait = min(wait, remaining * 0.9)
                logger.warning('%s timed out; retrying in %.1fs (attempt %d/%d)', operation_name, wait, attempt + 1, max_retries + 1)
                await asyncio.sleep(wait)
            else:
                logger.error('%s timed out after %d attempts', operation_name, max_retries + 1)
                raise ArxivTimeoutError(f'arXiv request timed out after {max_retries + 1} attempts. The arXiv API may be slow or overloaded. Please retry shortly.') from e
        except httpx.HTTPStatusError as e:
            if e.response is not None and e.response.status_code in (429, 503, 406):
                last_exception = e
                max_retries_for_status = settings.ARXIV_HTTP_406_MAX_RETRIES if e.response.status_code == 406 else max_retries
                retry_after = e.response.headers.get('Retry-After')
                if attempt < max_retries_for_status:
                    parsed_retry_after = _parse_retry_after_seconds(retry_after)
                    if parsed_retry_after is not None and parsed_retry_after > max_backoff:
                        if parsed_retry_after is None:
                            parsed_retry_after = 600.0 if e.response.status_code == 406 else 60.0
                        logger.warning('%s HTTP %d: Retry-After (%.1fs) exceeds max_backoff (%.1fs), returning immediately', operation_name, e.response.status_code, parsed_retry_after, max_backoff)
                        raise ArxivRateLimitError(f'arXiv is rate limiting this IP (HTTP {e.response.status_code}). Please wait {int(parsed_retry_after)} seconds before retrying.', status_code=e.response.status_code, retry_after_seconds=parsed_retry_after) from e
                    wait = _compute_backoff_seconds(attempt, retry_after, initial_backoff, max_backoff)
                    if max_total_time is not None:
                        remaining = max_total_time - (time.monotonic() - start_time)
                        if wait >= remaining:
                            if parsed_retry_after is None:
                                parsed_retry_after = _parse_retry_after_seconds(retry_after)
                            if parsed_retry_after is None:
                                parsed_retry_after = 600.0 if e.response.status_code == 406 else 60.0
                            logger.warning('%s HTTP %d: wait time (%.1fs) exceeds budget (%.1fs), returning immediately', operation_name, e.response.status_code, wait, remaining)
                            raise ArxivRateLimitError(f'arXiv is rate limiting this IP (HTTP {e.response.status_code}). Please wait {int(parsed_retry_after)} seconds before retrying.', status_code=e.response.status_code, retry_after_seconds=parsed_retry_after) from e
                        wait = min(wait, remaining * 0.9)
                    logger.warning('%s HTTP %d; retrying in %.1fs (attempt %d/%d)', operation_name, e.response.status_code, wait, attempt + 1, max_retries_for_status + 1)
                    await asyncio.sleep(wait)
                else:
                    parsed_retry_after = _parse_retry_after_seconds(retry_after)
                    if parsed_retry_after is None:
                        parsed_retry_after = 600.0 if e.response.status_code == 406 else 60.0
                    logger.error('%s HTTP %d after %d attempts', operation_name, e.response.status_code, max_retries_for_status + 1)
                    raise ArxivRateLimitError(f'arXiv is rate limiting this IP (HTTP {e.response.status_code}). Please wait {int(parsed_retry_after)} seconds before retrying.', status_code=e.response.status_code, retry_after_seconds=parsed_retry_after) from e
            else:
                raise
        except (ArxivTimeoutError, ArxivConnectionError, ArxivRateLimitError):
            raise
        except Exception:
            raise
    if last_exception:
        raise last_exception
    raise RuntimeError(f'{operation_name} failed after exhausting retries')

