def _normalize_abstract_mode(value: Any) -> str:
    """Return a valid abstract_mode or raise ValueError."""
    if value is None:
        return DEFAULT_ABSTRACT_MODE
    if not isinstance(value, str):
        raise ValueError(f'abstract_mode must be one of: none, snippet, full (got {type(value).__name__})')
    mode = value.strip().lower()
    if mode not in ABSTRACT_MODES:
        raise ValueError(f'abstract_mode must be one of: none, snippet, full (got {value!r})')
    return mode

