async def handle_search(arguments: Dict[str, Any]) -> List[types.TextContent]:
    """Handle paper search requests via the arXiv Atom API.

    Always uses raw HTTP so OpenSearch ``totalResults`` (corpus hit count)
    is available for every query — including those without date filters
    (see #189). Raw requests also avoid the arxiv package URL-encoding
    bug that breaks ``submittedDate`` ranges.
    """
    try:
        max_results = min(int(arguments.get('max_results', DEFAULT_MAX_RESULTS)), settings.MAX_RESULTS)
        start_arg = arguments.get('start', 0)
        try:
            start = max(0, int(start_arg))
        except (TypeError, ValueError):
            start = 0
        try:
            abstract_mode = _normalize_abstract_mode(arguments.get('abstract_mode', DEFAULT_ABSTRACT_MODE))
        except ValueError as e:
            return _error_response(str(e))
        base_query = arguments['query']
        date_from_arg = arguments.get('date_from')
        date_to_arg = arguments.get('date_to')
        categories = arguments.get('categories')
        try:
            sort_by_arg = _normalize_sort_by(arguments.get('sort_by', 'relevance'))
        except ValueError as e:
            return [types.TextContent(type='text', text=json.dumps({'status': 'error', 'message': str(e)}))]
        logger.debug('Starting search with query: %r, max_results: %s, start: %s, abstract_mode: %s', base_query, max_results, start, abstract_mode)
        if categories and (not _validate_categories(categories)):
            return _error_response('Invalid category provided. Please check arXiv category names.')
        try:
            optimized_query = _optimize_query(base_query) if base_query.strip() else ''
            results, total_results = await _raw_arxiv_search(query=optimized_query, max_results=max_results, sort_by=sort_by_arg, date_from=date_from_arg, date_to=date_to_arg, categories=categories, start=start)
            results = _apply_abstract_mode(results, abstract_mode)
            logger.info(f'Search completed: {len(results)} results returned')
            response_data = _build_search_response(results, total_results=total_results, start=start, abstract_mode=abstract_mode)
            return [types.TextContent(type='text', text=json.dumps(response_data, indent=2))]
        except ArxivRateLimitError as e:
            logger.warning('arXiv search rate limited after retries: %s', e)
            return _rate_limited_response(str(e), retry_after_seconds=e.retry_after_seconds, status_code=e.status_code)
        except httpx.HTTPStatusError as e:
            logger.error(f'arXiv API HTTP error: {e}')
            status = e.response.status_code if e.response is not None else 'unknown'
            return _error_response(f'arXiv API HTTP error (HTTP {status})')
        except ValueError as e:
            return _error_response(str(e))
    except ArxivRateLimitError as e:
        logger.warning('arXiv search rate limited after retries: %s', e)
        return _rate_limited_response(str(e), retry_after_seconds=e.retry_after_seconds, status_code=e.status_code)
    except Exception as e:
        logger.error(f'Unexpected search error: {e}')
        return _error_response(str(e))
